#!/usr/bin/env bash
# Build the Linux tarball from the binaries and version scripts/build.sh owns.
#
#   scripts/build.sh linux
#   packaging/linux/package.sh          # prints the tarball path
#
# The name comes from dist/VERSION, never from a second hard-coded version.
# The tarball ships the binary, this installer, the public docs generated by
# cmd/gensite, the license files, VERSION, and a SHA256SUMS that install.sh
# verifies before it copies anything.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
GO="${GO:-go}"

version_file="${ROOT}/dist/VERSION"
[[ -s "$version_file" ]] || {
	printf 'error: %s is missing; run scripts/build.sh linux first\n' "$version_file" >&2
	exit 1
}
version="$(tr -d '\r\n' <"$version_file")"
name="mailsense-${version}-linux-amd64"
stage="${ROOT}/dist/${name}"
tarball="${ROOT}/dist/${name}.tar.gz"

[[ -x "${ROOT}/dist/mailsense" ]] || {
	printf 'error: dist/mailsense is missing; run scripts/build.sh linux first\n' >&2
	exit 1
}
grep -a -F -q -- "$version" "${ROOT}/dist/mailsense" || {
	printf 'error: dist/mailsense does not embed %s; rebuild with scripts/build.sh linux\n' "$version" >&2
	exit 1
}

rm -rf -- "$stage"
mkdir -p -- "${stage}/docs/fr"
cp "${ROOT}/dist/mailsense" "${ROOT}/packaging/linux/install.sh" \
	"${ROOT}/README.md" "${ROOT}/LICENSE" "${ROOT}/NOTICE" "$stage/"
# The README and the landing pages point at the generated brand assets, so the
# package must carry them beside the pages, not only in the repository.
mkdir -p -- "${stage}/docs"
cp -R -- "${ROOT}/docs/assets" "${stage}/docs/"
printf '%s\n' "$version" >"${stage}/VERSION"

for lang in en fr; do
	mapfile -t pages < <(cd "$ROOT" && "$GO" run ./cmd/gensite -pages="$lang")
	((${#pages[@]})) || {
		printf 'error: cmd/gensite returned no %s pages\n' "$lang" >&2
		exit 1
	}
	(cd "$ROOT" && cp --parents "${pages[@]}" "$stage/")
done

(cd "$stage" && sha256sum mailsense >SHA256SUMS)
tar -C "${ROOT}/dist" -czf "$tarball" "$name"
rm -rf -- "$stage"
printf '%s\n' "$tarball"
